using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;
namespace Siderectomy {
 public sealed class LocalInteractionCheck : MonoBehaviour {
  string directory;readonly List<string> passed=new List<string>();
  public static void TryStart(){var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--local-interaction-check");if(i<0||i+1>=args.Length)return;var test=new GameObject("LocalInteractionCheck").AddComponent<LocalInteractionCheck>();test.directory=args[i+1];Directory.CreateDirectory(test.directory);Application.logMessageReceived+=test.OnLog;test.StartCoroutine(test.Run());}
  void OnLog(string text,string stack,LogType type){if(type!=LogType.Error&&type!=LogType.Exception)return;File.AppendAllText(Path.Combine(directory,"运行错误.txt"),text+"\n"+stack+"\n");Application.Quit(1);}
  void Check(bool ok,string name){if(!ok)throw new Exception("LOCAL_INTERACTION_CHECK: "+name);passed.Add("PASS "+name);}
  void ClickMap(DemoStarMap map,Vector2 local){FindObjectOfType<DemoMissionView>().CloseSecondaryMenu();Canvas.ForceUpdateCanvases();var data=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,map.rectTransform.TransformPoint(local))};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(data,hits);Check(hits.Count>0&&hits[0].gameObject==map.gameObject,"地图命中区域无遮挡");ExecuteEvents.Execute(map.gameObject,data,ExecuteEvents.pointerClickHandler);}
  IEnumerator Capture(string name){yield return new WaitForEndOfFrame();var camera=Camera.main;var canvas=FindObjectOfType<Canvas>();var mode=canvas.renderMode;var oldCamera=canvas.worldCamera;var oldTarget=camera.targetTexture;var active=RenderTexture.active;var target=new RenderTexture(1600,900,24);camera.targetTexture=target;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;var pixels=new Texture2D(1600,900,TextureFormat.RGB24,false);pixels.ReadPixels(new Rect(0,0,1600,900),0,0);pixels.Apply();File.WriteAllBytes(Path.Combine(directory,name+".png"),pixels.EncodeToPNG());camera.targetTexture=oldTarget;RenderTexture.active=active;canvas.renderMode=mode;canvas.worldCamera=oldCamera;Destroy(pixels);target.Release();Destroy(target);yield return null;}
  IEnumerator Run(){yield return null;yield return null;var view=FindObjectOfType<DemoMissionView>();var s=view.Simulation;var map=GameObject.Find("StarMap").GetComponent<DemoStarMap>();Canvas.ForceUpdateCanvases();
   Check(!s.GlobalProbe&&map.Positions.Count==0&&map.NodePositions.Count==0&&map.ShipPositions.Count==0,"进入关卡星系全黑且没有可选世界坐标");Check(GameObject.Find("BodyDirectory")==null&&GameObject.Find("BodyPreview")==null&&GameObject.Find("EnterLocal")==null,"探测前目录预览和局部入口隐藏");Check(!FindObjectsOfType<Text>().Any(t=>t.gameObject.activeInHierarchy&&s.Bodies.Any(b=>t.text==b.name)),"探测前不显示任何天体名称标签");Check(view.CurrentViewingText().Contains("未知星系")&&!view.CurrentViewingText().Contains("地球"),"未知星系右侧标题不泄露默认目标");string original=s.Selected;view.SelectBody("p7");view.EnterLocalView();Check(s.Selected==original&&string.IsNullOrEmpty(map.LocalBodyId),"未探测不能选择未知星球或进入局部");yield return Capture("00_开局未知星系");
   s.Level.aiScale=0;for(int i=0;i<6;i++)s.Res[i]=10000;foreach(var key in s.Carriers.Keys.ToArray())s.Carriers[key]=10;
   Check(s.Launch("probe","dust"),"未知星系无需选择星球即可付费发射探测");var scan=s.Missions.Last();Check(!s.Logs[0].Contains("地球"),"扫描日志不泄露隐藏目标名称");s.Paused=false;s.Advance(scan.left-.1);s.Paused=true;view.Refresh();yield return null;Canvas.ForceUpdateCanvases();Check(!s.GlobalProbe&&map.Positions.Count==0&&GameObject.Find("BodyDirectory")==null,"扫描在途未完成时仍不揭示星系");yield return Capture("00B_探测在途仍隐藏");s.Paused=false;s.Advance(.1);s.Paused=true;view.Refresh();yield return null;yield return null;Canvas.ForceUpdateCanvases();Check(s.GlobalProbe&&map.Positions.Count==s.Bodies.Count,"探测完成揭示全关卡天体与轨道");Check(GameObject.Find("BodyDirectory")!=null&&GameObject.Find("BodyPreview")!=null,"完成后目录与关联预览同步解锁");Check(!s.Find("p2").recon&&GameObject.Find("Node_p2n0")==null,"全貌揭示不自动完成深度侦察");yield return Capture("00C_探测完成星系全貌");view.SelectBody("p2");view.EnterLocalView();yield return null;Canvas.ForceUpdateCanvases();
   Check(map.NodePositions.Count==0,"未侦察局部图不显示设施节点");Check(GameObject.Find("Node_p2n0")==null,"未侦察列表不显示设施");Check(view.ReconDetails().Contains("待侦察")&&!view.ReconDetails().Contains("1536"),"未侦察详情不泄露人口与耐久");Check(!view.BriefingText().Contains("1536")&&!view.BriefingText().Contains("25中心"),"操作说明不绕过侦察暴露关卡数据");Check(!GameObject.Find("Situation").GetComponent<Text>().text.Contains("1650")&&!GameObject.Find("Situation").GetComponent<Text>().text.Contains("180.0"),"态势栏不泄露未知人口与备份");Check(view.CurrentViewingText().Contains("地球 / 上一级：太阳"),"当前查看显示天体及父级");yield return Capture("01_未侦察局部与预览");
   // Independent QA fixture funds ordinary paid missions. No hidden-state reveal shortcuts.
   s.Level.aiScale=0;for(int i=0;i<6;i++)s.Res[i]=10000;foreach(var key in s.Carriers.Keys.ToArray())s.Carriers[key]=10;
   Check(s.Launch("recon","dust"),"普通付费深度侦察提交");s.Paused=false;s.Advance(26);s.Paused=true;view.Refresh();yield return null;Canvas.ForceUpdateCanvases();Check(s.Body.recon&&map.NodePositions.Count==25,"侦察完成揭示25个中心");
   string node=s.Body.nodes.First(n=>n.type=="能源").id;ClickMap(map,map.NodePositions[node]);yield return null;Check(s.TargetNode==node,"局部图实际点击选中能源中心");Check(view.CurrentViewingText().Contains("能源中心")&&view.CurrentViewingText().Contains("上一级：地球"),"当前查看显示中心及父级");Check(GameObject.Find("Node_"+node).GetComponentInChildren<Text>().text.Contains("◀"),"图标与右侧列表目标联动");
   string other=s.Body.nodes.First(n=>n.type=="军事").id;view.SelectNode(other);yield return null;Check(s.TargetNode==other,"列表共享中心选择入口");view.SelectNode(node);view.QuickOperation("surface");var hp=s.Body.nodes.First(n=>n.id==node).hp;var before=(double[])s.Res.Clone();var cost=s.LaunchCost("surface",false,false);int stock=s.Carriers["dust"];Check(s.Launch("surface","dust"),"中心打击进入现有作业队列");var mission=s.Missions.Last();mission.intercept=0;Check(s.Body.nodes.First(n=>n.id==node).hp==hp,"投送前不即时扣耐久");for(int i=0;i<6;i++)Check(Math.Abs(s.Res[i]-(before[i]-cost[i]))<.001,"中心作业保持原费用"+i);Check(s.Carriers["dust"]==stock-1,"中心作业扣一个载体");
   double time=s.Time;int jobs=s.Jobs.Count;view.ExitLocalView();view.EnterLocalView();Check(ReferenceEquals(view.Simulation,s)&&s.Time==time&&s.Missions.Contains(mission)&&s.Jobs.Count==jobs&&s.Body.nodes.First(n=>n.id==node).hp==hp,"进出视图不重置时间损伤和队列");s.Paused=false;s.Advance(mission.left);s.Paused=true;view.Refresh();yield return null;Check(s.Body.nodes.First(n=>n.id==node).hp<hp,"到达后扣相应中心耐久");yield return Capture("02_局部中心与目标联动");
   view.SelectBody("p7");Check(s.Selected=="p7"&&!map.Positions.ContainsKey("p7"),"局部未渲染对象仍可通过目录选择");view.SelectBody("p2");view.ExitLocalView();s.Find("p2").pop-=16;s.Ships.Add(new DemoShip{id=901,body="p2",pop=8,left=60,total=60});s.Ships.Add(new DemoShip{id=902,body="p2",pop=8,left=50,total=60});s.Revision++;view.Refresh();yield return null;yield return null;Canvas.ForceUpdateCanvases();Check(map.ShipPositions.ContainsKey(902),"外逃舰绘制可选中位置");ClickMap(map,map.ShipPositions[902]);yield return null;Check(s.SelectedShip==902,"实际地图点击指定外逃舰");Check(view.CurrentViewingText().Contains("外逃舰 #902 / 上一级：地球"),"舰船当前查看父级正确");Check(GameObject.Find("OperationSelect").GetComponent<Dropdown>().options[GameObject.Find("OperationSelect").GetComponent<Dropdown>().value].text.Contains("拦截"),"点击舰船自动准备阻截作业");
   view.SelectShip(901);Check(s.SelectedShip==901,"舰船目录可换选目标");view.SelectShip(902);Check(s.Launch("blockade","satellite"),"指定舰船付费阻截发射");var intercept=s.Missions.Last();Check(intercept.ship==902,"在途任务保存舰船ID");yield return Capture("03_椭圆外逃与指定阻截");view.SelectShip(901);s.Paused=false;s.Advance(23.1);s.Paused=true;view.Refresh();yield return null;Check(s.Ships.First(x=>x.id==902).done&&!s.Ships.First(x=>x.id==901).done,"换选不改变已发射阻截目标");
   var origin=new Vector2(100,-150);var dest=new Vector2(900,-200);Check(Vector2.Distance(DemoStarMap.EscapePoint(origin,dest,0,901),origin)<.001f&&Vector2.Distance(DemoStarMap.EscapePoint(origin,dest,1,901),dest)<.001f,"椭圆航迹起终点正确");Check(Vector2.Distance(DemoStarMap.EscapePoint(origin,dest,.5f,901),(origin+dest)*.5f)>40,"航迹中点为椭圆弧非直线");
   File.WriteAllText(Path.Combine(directory,"局部与阻截验收.txt"),string.Join("\n",passed)+"\n使用独立资源充足夹具进行交互与结算验证，不代表真人难度平衡。\n");Application.Quit(0);
  }
 }
}
